/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy.ndimage import label
A=np.load('source_pixels.npz')['rgb'];pos=[]
for t,a in enumerate(A.astype(float)):
 r,g,b=a.transpose(2,0,1);Y,X=np.indices(r.shape)
 rm=(r-g>65)&(r-b>40)&(g<115)&(Y<75)
 ym=(g-b>30)&(r-b>20)&(Y<85)
 out=[]
 for m in [rm,ym]:
  l,n=label(m);o=[]
  for k in range(1,n+1):
   y,x=np.where(l==k)
   if len(x)>3:o.append((len(x),x.mean(),y.mean()))
  o.sort(key=lambda q:q[2]);out.append(o[0][1:] if o else [np.nan,np.nan])
 pos.append(out)
P=np.array(pos)
for t in range(96):print(t,P[t,0],P[t,1])
for r in [(0,38),(40,96)]:
 for o in range(2):
  z=P[r[0]:r[1],o,0];t=np.arange(r[0],r[1]);print(r,o,np.polyfit(t,z,2),np.polyfit(t,z,1))
np.save('.tmp/positions.npy',P)
PY"
